import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import Lottie from 'lottie-react';
import menuData from '../data/menuData';
import CategoryFilter from '../components/CategoryFilter';
import ProductGrid from '../components/ProductGrid';
import './Home.css';

function Home({ addToCart }) {
  const [activeCategory, setActiveCategory] = useState("all");
  const [filteredProducts, setFilteredProducts] = useState(menuData);
  const [addedMsg, setAddedMsg] = useState('');
  const [lottieData, setLottieData] = useState(null);
  const videoRef = useRef(null);

  useEffect(() => {
    if (activeCategory === "all") {
      setFilteredProducts(menuData);
    } else {
      setFilteredProducts(menuData.filter(p => p.category === activeCategory));
    }
  }, [activeCategory]);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.play().catch(() => {});
    }
  }, []);

  useEffect(() => {
    fetch('https://assets10.lottiefiles.com/packages/lf20_w98qte06.json')
      .then(res => res.json())
      .then(data => setLottieData(data))
      .catch(() => {});
  }, []);

  const handleAddToCart = (product, weight) => {
    addToCart(product, weight);
    setAddedMsg(`${product.name} (${weight})`);
    setTimeout(() => setAddedMsg(''), 2000);
  };

  return (
    <div className="home overflow-hidden">
      {/* Hero Section with Video Background */}
      <section className="relative min-h-[85vh] flex items-center justify-center bg-gradient-to-br from-red-900 via-red-700 to-red-600 overflow-hidden">
        <div className="absolute inset-0 overflow-hidden">
          <video ref={videoRef} autoPlay muted loop playsInline className="w-full h-full object-cover opacity-25" style={{ filter: 'blur(3px)' }}>
            <source src="https://cdn.coverr.co/videos/coverr-making-sweets-5645/1080p.mp4" type="video/mp4" />
          </video>
        </div>
        {/* Floating particles */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          {['🥨', '🍬', '🍮', '🥟', '🍪', '🧁'].map((emoji, i) => (
            <div key={i} className="absolute text-3xl opacity-15 animate-float" style={{ left: `${10 + i * 16}%`, top: `${20 + (i % 3) * 28}%`, animationDelay: `${i * 0.6}s` }}>{emoji}</div>
          ))}
        </div>
        <div className="relative z-10 text-center text-white px-6 max-w-5xl mx-auto">
          <div className="inline-block px-6 py-2 bg-white/10 backdrop-blur rounded-full text-sm font-medium mb-6 border border-white/20">🏆 Traditional Taste Since Years</div>
          <h1 className="text-5xl md:text-7xl font-bold mb-4 font-serif leading-tight">
            Riddhi Siddhi<br /><span className="text-yellow-400">Modak Farsan</span>
          </h1>
          <p className="text-2xl md:text-3xl text-yellow-300 font-semibold mb-4">✨ Shuddh Swad, Hamari Pehchaan ✨</p>
          <p className="text-lg md:text-xl text-white/80 max-w-2xl mx-auto mb-8 leading-relaxed">
            Authentic Maharashtrian namkeen, farsan & sweets made with love, tradition, and the finest ingredients
          </p>
          <div className="flex flex-wrap gap-4 justify-center mb-12">
            <a href="#catalog" className="px-8 py-4 bg-yellow-400 text-red-900 rounded-full font-bold text-lg hover:bg-yellow-300 transition-all duration-300 transform hover:scale-105 hover:shadow-2xl">🥨 Explore Our Menu</a>
            <Link to="/checkout" className="px-8 py-4 bg-white/10 backdrop-blur text-white rounded-full font-bold text-lg border-2 border-white/30 hover:bg-white/20 transition-all duration-300 transform hover:scale-105">🛵 Order Now</Link>
          </div>
          <div className="flex justify-center gap-8 md:gap-16">
            {[{ num: '19+', label: 'Products' }, { num: '3km', label: 'Delivery Radius' }, { num: '🚚', label: 'Free Delivery' }].map((s, i) => (
              <div key={i} className="text-center"><div className="text-3xl md:text-4xl font-bold text-yellow-400">{s.num}</div><div className="text-sm text-white/70 mt-1">{s.label}</div></div>
            ))}
          </div>
        </div>
        {/* Scroll indicator */}
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 animate-bounce"><div className="w-6 h-10 border-2 border-white/30 rounded-full flex justify-center"><div className="w-1.5 h-3 bg-white/50 rounded-full mt-2 animate-pulse"></div></div></div>
      </section>

      {/* Lottie + Delivery Info Section */}
      <section className="py-10 bg-gradient-to-r from-red-50 to-orange-50">
        <div className="container mx-auto px-4 max-w-5xl">
          <div className="flex flex-col md:flex-row items-center justify-center gap-8">
            <div className="w-28 h-28">
              {lottieData ? (
                <Lottie animationData={lottieData} loop autoplay style={{ width: '100%', height: '100%' }} />
              ) : (
                <span className="text-5xl flex items-center justify-center h-full animate-bounce">🚚</span>
              )}
            </div>
            <div className="text-center md:text-left">
              <h3 className="text-2xl font-bold text-red-800">Free Delivery on Orders Above ₹300</h3>
              <p className="text-gray-600">Freshly prepared snacks delivered to your doorstep within 1-3 km radius</p>
              <div className="flex gap-4 mt-3 text-sm">
                <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full font-medium">✓ Next-day delivery</span>
                <span className="px-3 py-1 bg-green-100 text-green-700 rounded-full font-medium">✓ COD & UPI</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Catalog Section */}
      <section id="catalog" className="py-16 bg-gradient-to-b from-white to-orange-50">
        <div className="container mx-auto px-4">
          <h2 className="text-4xl md:text-5xl font-serif font-bold text-center text-red-800 mb-4">Our Delicious Menu</h2>
          <p className="text-center text-gray-500 text-lg mb-8">Browse our wide range of traditional delicacies</p>

          {/* Category Filters */}
          <div className="mb-10">
            <CategoryFilter activeCategory={activeCategory} onCategoryChange={setActiveCategory} />
          </div>

          {/* Products Grid */}
          <ProductGrid products={filteredProducts} onAddToCart={handleAddToCart} />
        </div>
      </section>

      {/* Quality Section */}
      <section className="py-20 bg-gradient-to-br from-red-900 via-red-800 to-red-700 text-white">
        <div className="container mx-auto px-4 max-w-6xl">
          <h2 className="text-4xl md:text-5xl font-serif font-bold text-center text-yellow-400 mb-4">Why Choose Us?</h2>
          <p className="text-center text-white/70 text-lg mb-16">We prioritize quality, taste, and your satisfaction</p>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
            {[
              { icon: '🥇', title: 'Premium Quality', desc: 'We use only the finest ingredients, ensuring every bite delivers authentic taste' },
              { icon: '👩‍🍳', title: 'Traditional Recipes', desc: 'Our recipes have been passed down through generations, preserving authentic flavors' },
              { icon: '🧹', title: 'Hygiene First', desc: 'We maintain the highest standards of cleanliness in our kitchen and packaging' },
              { icon: '🚚', title: 'Fast Delivery', desc: 'Next-day delivery for regular items, straight to your doorstep' }
            ].map((item, i) => (
              <div key={i} className="text-center p-8 bg-white/5 backdrop-blur rounded-2xl border border-white/10 hover:bg-white/10 transition-all duration-500 transform hover:-translate-y-2">
                <div className="text-5xl mb-6 group-hover:animate-bounce">{item.icon}</div>
                <h3 className="text-xl font-bold mb-3 font-serif">{item.title}</h3>
                <p className="text-white/70 text-sm leading-relaxed">{item.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Contact Section */}
      <section className="py-20 bg-gradient-to-b from-white to-orange-50">
        <div className="container mx-auto px-4">
          <div className="max-w-4xl mx-auto bg-white rounded-3xl shadow-2xl p-8 md:p-12">
            <h2 className="text-3xl md:text-4xl font-serif font-bold text-center text-red-800 mb-4">📍 Visit Our Shop</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-10">
              <div className="flex items-start gap-4"><span className="text-2xl flex-shrink-0">🏪</span><div><h4 className="font-bold text-red-800 mb-1">Address</h4><p className="text-gray-600 text-sm">165/2A, Saket Nagar, Bhopal<br />Near AIIMS, In Front of Bhopal Public School</p></div></div>
              <div className="flex items-start gap-4"><span className="text-2xl flex-shrink-0">📞</span><div><h4 className="font-bold text-red-800 mb-1">Call Us</h4><p className="text-gray-600 text-sm"><a href="tel:7974613110" className="text-red-700 font-semibold">7974613110</a> / <a href="tel:9893378872" className="text-red-700 font-semibold">9893378872</a></p></div></div>
              <div className="flex items-start gap-4"><span className="text-2xl flex-shrink-0">🕐</span><div><h4 className="font-bold text-red-800 mb-1">Hours</h4><p className="text-gray-600 text-sm">Mon-Sat: 9AM-9PM<br />Sun: 10AM-6PM</p></div></div>
            </div>
            <div className="text-center">
              <Link to="/checkout" className="inline-flex items-center gap-2 px-10 py-4 bg-gradient-to-r from-red-700 to-red-500 text-white rounded-full font-bold text-lg hover:shadow-2xl hover:scale-105 transition-all duration-300">🛵 Order Now for Delivery</Link>
            </div>
          </div>
        </div>
      </section>

      {/* Toast */}
      {addedMsg && (
        <div className="fixed bottom-6 right-6 bg-green-500 text-white px-6 py-3 rounded-xl shadow-2xl z-50 animate-slide-up flex items-center gap-2">
          <span>✅</span><span className="font-medium">{addedMsg} added to cart!</span>
        </div>
      )}
    </div>
  );
}

export default Home;
